import importlib.util, random, itertools, time
from pathlib import Path
from collections import Counter

def load(pid):
    spec = importlib.util.spec_from_file_location(pid, Path('solutions') / f'{pid}.py')
    mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    return mod.Solution()

def semi_cost(t):
    L=len(t)
    if L < 2: return 10**9
    best=10**9
    for d in range(1,L):
        if L%d: continue
        c=0
        for r in range(d):
            a=t[r::d]
            c += sum(a[i]"'!=a[-1-i] for i in range(len(a)//2))
        best=min(best,c)
    return best

def brute2879(s,k):
    n=len(s); best=10**9
    for cuts in itertools.combinations(range(1,n),k-1):
        bounds=(0,)+cuts+(n,)
        total=0
        for a,b in zip(bounds,bounds[1:]):
            total += semi_cost(s[a:b])
        best=min(best,total)
    return best

def brute3223(w,k):
    ans=0
    for i in range(len(w)):
        cnt=Counter()
        for j in range(i,len(w)):
            if j>i and abs(ord(w[j])-ord(w[j-1]))>2: break
            cnt[w[j]]+=1
            if all(v==k for v in cnt.values()): ans+=1
    return ans

def brute3091(nums,l,r):
    freq=Counter(nums); vals=list(freq)
    ans=0
    for choices in itertools.product(*(range(freq[v]+1) for v in vals)):
        total=sum(c*v for c,v in zip(choices,vals))
        if l<=total<=r: ans+=1
    return ans%(10**9+7)

sol2879=load('"'2879'); sol3223=load('3223'); sol3091=load('3091')
random.seed(20261022)
for n in range(2,10):
    for _ in range(40):
        s=''.join(random.choice('abc') for _ in range(n))
        k=random.randint(1,n//2)
        a=sol2879.minimumChanges(s,k); b=brute2879(s,k)
        if a"'!=b: raise SystemExit(f'"'2879 mismatch {s=} {k=} {a=} {b=}')
print('2879 random OK')
for n in range(1,13):
    for _ in range(100):
        w=''.join(random.choice('abcde') for _ in range(n))
        k=random.randint(1,n)
        a=sol3223.countCompleteSubstrings(w,k); b=brute3223(w,k)
        if a"'!=b: raise SystemExit(f'"'3223 mismatch {w=} {k=} {a=} {b=}')
print('3223 random OK')
for n in range(1,9):
    for _ in range(100):
        nums=[random.randint(0,5) for _ in range(n)]
        l=random.randint(0,15); r=random.randint(l,15)
        a=sol3091.countSubMultisets(nums,l,r); b=brute3091(nums,l,r)
        if a"'!=b: raise SystemExit(f'"'3091 mismatch {nums=} {l=} {r=} {a=} {b=}')
print('3091 random OK')

start=time.perf_counter(); print('3223 stress', sol3223.countCompleteSubstrings('a'*100000, 1), f'{time.perf_counter()-start:.3f}s')
nums=[1]*20000; start=time.perf_counter(); print('3091 stress', sol3091.countSubMultisets(nums,0,20000), f'{time.perf_counter()-start:.3f}s')
s='a'*200; start=time.perf_counter(); print('2879 stress', sol2879.minimumChanges(s,100), f'{time.perf_counter()-start:.3f}s')
